type Location = {
  line: number;
  column: number;
};

type Node =
  | { type: "text"; value: string }
  | { type: "value"; path: string; escaped: boolean; location: Location }
  | {
      type: "block";
      kind: "if" | "each";
      path: string;
      body: Node[];
      alternate: Node[] | null;
      location: Location;
    };

type BlockNode = Extract<Node, { type: "block" }>;

type Frame = {
  block: BlockNode;
  parent: Node[];
  inElse: boolean;
};

type Scope = {
  value: unknown;
  index: number;
};

const MISSING = Symbol("missing");

export class TemplateError extends Error {
  readonly line: number;
  readonly column: number;

  constructor(message: string, location: Location) {
    super(`${message} at line ${location.line}, column ${location.column}`);
    this.name = "TemplateError";
    this.line = location.line;
    this.column = location.column;
  }
}

function locationAt(source: string, offset: number): Location {
  let line = 1;
  let column = 1;
  for (let i = 0; i < offset; i++) {
    if (source.charCodeAt(i) === 10) {
      line++;
      column = 1;
    } else {
